def must_mention(*keywords):
    # returns a checker: passes if every keyword appears
    def check(output):
        low = output.lower()
        return all(k.lower() in low for k in keywords)
    return check

case = {
    "input": "Summarize our refund policy.",
    "check": must_mention("30 days", "delivery"),
}
print(case["check"]("Refunds within 30 days of delivery."))  # True
print(case["check"]("Refunds are quick."))                   # False

