def must_include(*keywords):
    # a check that passes only if every keyword appears
    def check(output):
        low = output.lower()
        return all(k.lower() in low for k in keywords)
    return check

# golden set: input + a behavior check (not an exact string)
golden_set = [
    {"id": "refund", "input": "refund window?",
     "check": must_include("30 days")},
    {"id": "ship", "input": "ship internationally?",
     "check": must_include("no")},
]

# a mock agent with canned answers
def mock_agent(q):
    answers = {"refund window?": "Refunds are accepted within 30 days.",
               "ship internationally?": "No, we only ship domestically."}
    return answers[q]

for case in golden_set:
    out = mock_agent(case["input"])
    print(case["id"], case["check"](out))

import json, hashlib

def dataset_version(cases):
    blob = json.dumps([c["id"] for c in cases], sort_keys=True).encode()
    return hashlib.sha256(blob).hexdigest()[:8]

def must_include(*kw):
    return lambda o: all(k.lower() in o.lower() for k in kw)

def run_eval(agent, cases):
    passed, failures = 0, []
    for c in cases:
        out = agent(c["input"])
        ok = c["check"](out)
        passed += ok
        if not ok:
            failures.append({"id": c["id"], "output": out})
    return passed / len(cases), failures

cases = [
    {"id": "refund", "input": "refund?", "check": must_include("30 days")},
    {"id": "oos", "input": "weather?", "check": must_include("out of scope")},
]

def agent(q):
    # correctly refuses? no -- it hallucinates the weather
    return {"refund?": "Within 30 days.",
            "weather?": "It's sunny in Paris!"}[q]

score, failures = run_eval(agent, cases)
print(f"version={dataset_version(cases)} score={score:.2f}")
print("failing:", [f["id"] for f in failures])

