def run_eval(agent, cases):
    if not cases:
        # avoid ZeroDivisionError on an empty set
        return 0.0, []
    passed = 0
    failures = []
    for c in cases:
        output = agent(c["input"])
        ok = c["check"](output)
        if ok:
            passed += 1
        else:
            failures.append({"id": c["id"], "output": output})
    score = passed / len(cases)
    return score, failures

