from collections import defaultdict

def run_eval(agent, cases):
    if not cases:
        return {"overall": 0.0, "by_category": {}}
    stats = defaultdict(lambda: {"passed": 0, "total": 0})
    passed = 0
    for c in cases:
        out = agent(c["input"])
        ok = bool(c["check"](out))
        cat = c.get("category", "uncategorized")
        stats[cat]["total"] += 1
        stats[cat]["passed"] += ok
        passed += ok
    by_category = {
        cat: round(s["passed"] / s["total"], 2)
        for cat, s in stats.items()
    }
    return {"overall": round(passed / len(cases), 2),
            "by_category": by_category}

if __name__ == "__main__":
    def has(*kw):
        return lambda o: all(k in o.lower() for k in kw)
    cases = [
        {"input": "refund?", "check": has("30 days"), "category": "happy"},
        {"input": "weather?", "check": has("out of scope"), "category": "oos"},
    ]
    agent = lambda q: {"refund?": "within 30 days",
                       "weather?": "it's sunny"}[q]
    print(run_eval(agent, cases))
